param([Parameter(Mandatory)][string]$Output)
$ErrorActionPreference='Stop';$cecil='C:/Program Files/Unity/Hub/Editor/6000.6.5f1/Editor/Data/Tools/Burst/Client/Unity.Burst.Cecil.dll';[Reflection.Assembly]::LoadFrom($cecil)|Out-Null
$rows=[Collections.Generic.List[object]]::new();$errors=[Collections.Generic.List[object]]::new()
function ScanType($type,$file){foreach($method in $type.Methods){if(!$method.HasBody){continue};foreach($instruction in $method.Body.Instructions){$target=$instruction.Operand;if($target -is [Mono.Cecil.MethodReference] -and $target.DeclaringType.FullName -eq 'UnityEngine.Connect.UnityConnectSettings'){$rows.Add(@{assembly=$file;caller=$method.FullName;opcode=$instruction.OpCode.Name;callee=$target.FullName;offset=$instruction.Offset})}}};foreach($nested in $type.NestedTypes){ScanType $nested $file}}
foreach($file in Get-ChildItem 'C:/Program Files/Unity/Hub/Editor/6000.6.5f1/Editor/Data/Managed' -Filter 'UnityEditor*.dll' -Recurse){try{$asm=[Mono.Cecil.AssemblyDefinition]::ReadAssembly($file.FullName);try{foreach($type in $asm.MainModule.Types){ScanType $type $file.FullName}}finally{$asm.Dispose()}}catch{$errors.Add(@{file=$file.FullName;error=$_.Exception.Message})}}
@{scope='Read-only IL member-reference scan; no Unity assembly executed or altered';calls=$rows;errors=$errors;cecilSHA256=(Get-FileHash $cecil).Hash}|ConvertTo-Json -Depth 8|Set-Content -Encoding utf8 $Output
